import os, sys
from xml.etree import ElementTree as ET

W = '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}'

def para_text(p):
    parts = []
    for node in p.iter():
        tag = node.tag
        if tag == W + 't':
            parts.append(node.text or '')
        elif tag == W + 'delText':
            parts.append('[DEL:' + (node.text or '') + ']')
        elif tag == W + 'tab':
            parts.append('\t')
        elif tag == W + 'br':
            parts.append('\n')
    return ''.join(parts)

root = 'unpacked'
print('=== FILES IN UNPACKED DIR ===')
for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        print(os.path.join(dirpath, fn))

doc_path = os.path.join(root, 'word', 'document.xml')
tree = ET.parse(doc_path)
doc = tree.getroot()
body = doc.find(W + 'body')

print('\n=== DOCUMENT PARAGRAPH OUTLINE ===')
paras = body.findall(W + 'p')
for i, p in enumerate(paras):
    pstyle = ''
    ppr = p.find(W + 'pPr')
    if ppr is not None:
        st = ppr.find(W + 'pStyle')
        if st is not None:
            pstyle = st.get(W + 'val')
    txt = para_text(p)
    snippet = txt[:120].replace('\n', '\\n')
    print(f'[{i}] style={pstyle!r} text={snippet!r}')

print('\n=== OTHER BODY CHILDREN ===')
for i, child in enumerate(body):
    tag = child.tag.replace(W, 'w:')
    if tag != 'w:p':
        print(f'[{i}] {tag}')

print('\n=== STYLES AVAILABLE ===')
styles_path = os.path.join(root, 'word', 'styles.xml')
if os.path.exists(styles_path):
    stree = ET.parse(styles_path)
    for st in stree.getroot().findall(W + 'style'):
        sid = st.get(W + 'styleId')
        name_el = st.find(W + 'name')
        name = name_el.get(W + 'val') if name_el is not None else ''
        print(f'styleId={sid!r} name={name!r}')

import os, sys

root = 'unpacked'
for dirpath, dirnames, filenames in os.walk(root):
    for f in filenames:
        print(os.path.relpath(os.path.join(dirpath, f), root))

